package com.auca.administrator;
import com.auca.abstracts.Person; import com.auca.exceptions.ValidationException; import java.time.LocalDate;
public class Administrator extends Person {
 private String staffNumber,jobTitle,assignedOffice; private LocalDate employmentDate; private int accessLevel; private boolean active;
 public Administrator(String personId,String firstName,String lastName,String email,String phoneNumber,LocalDate dob,String staffNumber,String jobTitle,String assignedOffice,LocalDate employmentDate,int accessLevel,boolean active){super(personId,firstName,lastName,email,phoneNumber,dob);this.staffNumber=staffNumber;this.jobTitle=jobTitle;this.assignedOffice=assignedOffice;this.employmentDate=employmentDate;this.accessLevel=accessLevel;this.active=active;}
 public String getRoleDescription(){return "Administrator";} public boolean isActive(){return active;}
 public void validate() throws ValidationException {super.validate();if(staffNumber==null||staffNumber.isBlank()||jobTitle==null||jobTitle.isBlank()||assignedOffice==null||assignedOffice.isBlank()||employmentDate==null||accessLevel<1)throw new ValidationException("Invalid administrator details.");}
 public String getStaffNumber(){return staffNumber;} public void setStaffNumber(String v){staffNumber=v;} public String getJobTitle(){return jobTitle;} public void setJobTitle(String v){jobTitle=v;} public String getAssignedOffice(){return assignedOffice;} public void setAssignedOffice(String v){assignedOffice=v;} public LocalDate getEmploymentDate(){return employmentDate;} public void setEmploymentDate(LocalDate v){employmentDate=v;} public int getAccessLevel(){return accessLevel;} public void setAccessLevel(int v){accessLevel=v;} public boolean isAdministratorActive(){return active;} public void setActive(boolean v){active=v;} public String getId(){return staffNumber;} public String getDisplayName(){return getFirstName()+" "+getLastName()+" ("+staffNumber+")";} public String toString(){return "ADMINISTRATOR\n"+super.toString()+", Staff No: "+staffNumber+", Title: "+jobTitle+", Office: "+assignedOffice+", Employment date: "+employmentDate+", Access: "+accessLevel+", Active: "+active;}
}
